window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-675a9b1f1e3a1705"]={"versions": [{"id": "FIG-675a9b1f1e3a1705", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>seq Lifecycle Control of UdsTransportProtocol</code>) im Kontext der AUTOSAR Adaptive Platform (SWS Diagnostics). Es modelliert den Lebenszyklus und das Kontrollregime für UDS-Transportprotokoll-Handler durch die zentrale Diagnoseverwaltung. Das Diagramm gliedert den Ablauf über vertikale Abschnitte in drei Zustandsphasen des Diagnostic Management: <code>[DM Startup]</code>, <code>[DM Run]</code> und <code>[DM Shutdown]</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>DM Instance: DM_Generic</code>: Instanz des generischen Diagnostic Management (DM), annotiert mit der Spezifikationsnotiz <code>Implements UdsTransportProtocolMgr</code>. Sie fungiert als Initiator und Manager des Transportprotokolls.</li>\n<li><code>Instance1: UdsTransportProtocolHandlerImpl</code>: Konkrete Implementierungsinstanz des UDS-Transportprotokoll-Handlers (<code>UdsTransportProtocolHandler</code>).</li>\n<li>Schnittstellen und Funktionsaufrufe:</li>\n<li>Konstruktor: <code>UdsTransportProtocolHandler(UdsTransportProtocolHandlerID, UdsTransportProtocolMgr&amp;)</code> zur Instanziierung und Übergabe der Handler-ID sowie der Manager-Referenz.</li>\n<li>Initialisierung: Synchroner Aufruf <code>Initialize()</code> mit Ausführungsausprägung und Rückkehr (Return Message).</li>\n<li>Betriebssteuerung: <code>Start()</code> zur Aktivierung des Protokollhandlers.</li>\n<li>Interaktionsreferenz: <code>ref</code>-Kompaktblock <code>UDS Request Processing</code>.</li>\n<li>Terminierungssteuerung: <code>Stop()</code> zum Anhalten des Handlers.</li>\n<li>Rückmeldung/Callback: Asynchroner/synchroner Aufruf <code>HandlerStopped(UdsTransportProtocolHandlerID)</code> vom Handler an die DM-Instanz.</li>\n<li>Destruktor: <code>~UdsTransportProtocolHandler()</code> zur Zerstörung der Handler-Instanz, markiert durch ein Terminierungskreuz an der Lebenslinie.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>DM Startup</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>DM Instance</code> erzeugt eine neue Instanz <code>Instance1: UdsTransportProtocolHandlerImpl</code> über den Konstruktoraufruf <code>UdsTransportProtocolHandler(UdsTransportProtocolHandlerID, UdsTransportProtocolMgr&amp;)</code>.</li>\n<li>Anschließend ruft die <code>DM Instance</code> synchron <code>Initialize()</code> auf dem Handler auf, woraufhin die Rückkehr erfolgt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>DM Run</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>DM Instance</code> signalisiert Betriebsbereitschaft über <code>Start()</code>.</li>\n<li>Innerhalb der aktiven Betriebsphase erfolgt die reguläre Diagnosekommunikation, dargestellt über das Referenz-Fragment <code>UDS Request Processing</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>DM Shutdown</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>DM Instance</code> leitet den Shutdown über den Aufruf <code>Stop()</code> ein.</li>\n<li>Der Handler schließt ausstehende Vorgänge ab und meldet seinen Vollzug via <code>HandlerStopped(UdsTransportProtocolHandlerID)</code> an die <code>DM Instance</code>.</li>\n<li>Abschließend zerstört die <code>DM Instance</code> den Handler über <code>~UdsTransportProtocolHandler()</code>, womit die Lebenslinie der Instanz endet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Protokollhandler für UDS-Transportprotokolle in AUTOSAR Adaptive müssen das Lifecycle-Interface unterstützen und sich strikt an die Phasen Startup, Run und Shutdown halten.</li>\n<li>Bei der Konstruktion muss dem Handler seine eindeutige <code>UdsTransportProtocolHandlerID</code> sowie eine Referenz auf den implementierten <code>UdsTransportProtocolMgr</code> übergeben werden, damit Rückmeldungen wie <code>HandlerStopped(...)</code> adressierbar sind.</li>\n<li>Die Diagnoseanforderungsverarbeitung (<code>UDS Request Processing</code>) darf erst nach erfolgreichem <code>Start()</code> erfolgen.</li>\n<li>Während des Shutdowns muss sichergestellt werden, dass vor der Freigabe/Zerstörung (<code>~UdsTransportProtocolHandler()</code>) die Bestätigung <code>HandlerStopped</code> empfangen wurde.</li>\n</ul>"}, {"id": "FIG-286a320940c88a46", "releases": ["R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>seq Lifecycle Control of UdsTransportProtocol</code>) im Kontext der AUTOSAR Adaptive Platform (SWS Diagnostics). Es modelliert den Lebenszyklus und das Kontrollregime für UDS-Transportprotokoll-Handler durch die zentrale Diagnoseverwaltung. Das Diagramm gliedert den Ablauf über vertikale Abschnitte in drei Zustandsphasen des Diagnostic Management: <code>[DM Startup]</code>, <code>[DM Run]</code> und <code>[DM Shutdown]</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>DM Instance: DM_Generic</code>: Instanz des generischen Diagnostic Management (DM), annotiert mit der Spezifikationsnotiz <code>Implements UdsTransportProtocolMgr</code>. Sie fungiert als Initiator und Manager des Transportprotokolls.</li>\n<li><code>Instance1: UdsTransportProtocolHandlerImpl</code>: Konkrete Implementierungsinstanz des UDS-Transportprotokoll-Handlers (<code>UdsTransportProtocolHandler</code>).</li>\n<li>Schnittstellen und Funktionsaufrufe:</li>\n<li>Konstruktor: <code>UdsTransportProtocolHandler(UdsTransportProtocolHandlerID, UdsTransportProtocolMgr&amp;)</code> zur Instanziierung und Übergabe der Handler-ID sowie der Manager-Referenz.</li>\n<li>Initialisierung: Synchroner Aufruf <code>Initialize()</code> mit Ausführungsausprägung und Rückkehr (Return Message).</li>\n<li>Betriebssteuerung: <code>Start()</code> zur Aktivierung des Protokollhandlers.</li>\n<li>Interaktionsreferenz: <code>ref</code>-Kompaktblock <code>UDS Request Processing</code>.</li>\n<li>Terminierungssteuerung: <code>Stop()</code> zum Anhalten des Handlers.</li>\n<li>Rückmeldung/Callback: Asynchroner/synchroner Aufruf <code>HandlerStopped(UdsTransportProtocolHandlerID)</code> vom Handler an die DM-Instanz.</li>\n<li>Destruktor: <code>~UdsTransportProtocolHandler()</code> zur Zerstörung der Handler-Instanz, markiert durch ein Terminierungskreuz an der Lebenslinie.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>DM Startup</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>DM Instance</code> erzeugt eine neue Instanz <code>Instance1: UdsTransportProtocolHandlerImpl</code> über den Konstruktoraufruf <code>UdsTransportProtocolHandler(UdsTransportProtocolHandlerID, UdsTransportProtocolMgr&amp;)</code>.</li>\n<li>Anschließend ruft die <code>DM Instance</code> synchron <code>Initialize()</code> auf dem Handler auf, woraufhin die Rückkehr erfolgt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>DM Run</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>DM Instance</code> signalisiert Betriebsbereitschaft über <code>Start()</code>.</li>\n<li>Innerhalb der aktiven Betriebsphase erfolgt die reguläre Diagnosekommunikation, dargestellt über das Referenz-Fragment <code>UDS Request Processing</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>DM Shutdown</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>DM Instance</code> leitet den Shutdown über den Aufruf <code>Stop()</code> ein.</li>\n<li>Der Handler schließt ausstehende Vorgänge ab und meldet seinen Vollzug via <code>HandlerStopped(UdsTransportProtocolHandlerID)</code> an die <code>DM Instance</code>.</li>\n<li>Abschließend zerstört die <code>DM Instance</code> den Handler über <code>~UdsTransportProtocolHandler()</code>, womit die Lebenslinie der Instanz endet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Protokollhandler für UDS-Transportprotokolle in AUTOSAR Adaptive müssen das Lifecycle-Interface unterstützen und sich strikt an die Phasen Startup, Run und Shutdown halten.</li>\n<li>Bei der Konstruktion muss dem Handler seine eindeutige <code>UdsTransportProtocolHandlerID</code> sowie eine Referenz auf den implementierten <code>UdsTransportProtocolMgr</code> übergeben werden, damit Rückmeldungen wie <code>HandlerStopped(...)</code> adressierbar sind.</li>\n<li>Die Diagnoseanforderungsverarbeitung (<code>UDS Request Processing</code>) darf erst nach erfolgreichem <code>Start()</code> erfolgen.</li>\n<li>Während des Shutdowns muss sichergestellt werden, dass vor der Freigabe/Zerstörung (<code>~UdsTransportProtocolHandler()</code>) die Bestätigung <code>HandlerStopped</code> empfangen wurde.</li>\n</ul>"}], "trans": [{"from": "FIG-675a9b1f1e3a1705", "to": "FIG-286a320940c88a46", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-286a320940c88a46", "to": "FIG-675a9b1f1e3a1705", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
